<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\{AdInventoryReservation,AdPlacement};use Illuminate\Http\Request;use Inertia\Inertia;
class AdInventoryController extends Controller{public function index(Request $r){$from=$r->date('from')?:today();$to=$r->date('to')?:today()->addDays(90);$placements=AdPlacement::where('is_active',true)->with(['campaigns'])->orderBy('name')->get()->map(function($p)use($from,$to){$reservations=AdInventoryReservation::with(['campaign','proposal'])->where('ad_placement_id',$p->id)->whereIn('status',['hold','committed'])->whereDate('starts_on','<=',$to)->whereDate('ends_on','>=',$from)->orderBy('starts_on')->get();$reserved=(int)$reservations->sum('quantity');return ['id'=>$p->id,'name'=>$p->name,'code'=>$p->code,'capacity'=>$p->max_active_campaigns,'reserved'=>$reserved,'available'=>max(0,$p->max_active_campaigns-$reserved),'reservations'=>$reservations];});return Inertia::render('Admin/Sponsorship/Inventory/Index',['placements'=>$placements,'filters'=>['from'=>$from->toDateString(),'to'=>$to->toDateString()]]);}}
